// GENERATED by scripts/sync-skill.mjs from prototype/paint.js. Edit the prototype, not this copy.
// Style-aware shape painter (canvas). Every body part goes through paint(), so a
// style changes HOW shapes are inked/shaded without each part knowing about it:
//   - line weight variation (thick on the side away from the light, thin toward it)
//   - stroke-behind outlines (only the outer half of the stroke shows: clean unions)
//   - coloured line art (cel), hard 2-tone cel shadow + rim light crescents
//   - ink: boiling double strokes (re-jittered at the boil rate), off-register fill, hatching
// Shapes are Path2D objects so the same geometry can be filled, stroked, clipped
// and offset to make shadow/rim crescents.

/** Build a Path2D with a builder callback (p) => { p.moveTo ... }. */
export function makePath(build) {
  const p = new Path2D();
  build(p);
  return p;
}

/** Polyline path; closed by default. */
export function polyPath(pts, closed = true) {
  const p = new Path2D();
  if (!pts.length) return p;
  p.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) p.lineTo(pts[i].x, pts[i].y);
  if (closed) p.closePath();
  return p;
}

/** Convert a device-space vector to the current local space (linear part only). */
export function toLocal(ctx, vx, vy) {
  const m = ctx.getTransform();
  const det = m.a * m.d - m.b * m.c || 1;
  return { x: (m.d * vx - m.c * vy) / det, y: (-m.b * vx + m.a * vy) / det };
}

/** Darken/lighten a hex colour by mixing toward black (k<0) or white (k>0). */
export function shadeHex(hex, k) {
  const n = parseInt(hex.slice(1), 16);
  const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => Math.round(k < 0 ? c * (1 + k) : c + (255 - c) * k));
  return `#${ch.map((c) => c.toString(16).padStart(2, '0')).join('')}`;
}

// deterministic jitter for boiling lines
function hash(a, b) {
  let h = Math.imul(a ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(b + 0x7f4a7c15, 0xc2b2ae35);
  h ^= h >>> 13;
  h = Math.imul(h, 0x27d4eb2f);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

const hatchCache = new WeakMap();
function hatchPattern(ctx, color) {
  let byColor = hatchCache.get(ctx);
  if (!byColor) hatchCache.set(ctx, (byColor = new Map()));
  if (byColor.has(color)) return byColor.get(color);
  const c = document.createElement('canvas');
  c.width = 6;
  c.height = 6;
  const g = c.getContext('2d');
  g.strokeStyle = color;
  g.lineWidth = 0.9;
  g.beginPath();
  for (const o of [-6, 0, 6]) {
    g.moveTo(o, 6);
    g.lineTo(o + 6, 0);
  }
  g.stroke();
  const pat = ctx.createPattern(c, 'repeat');
  byColor.set(color, pat);
  return pat;
}

/** Fill the part of `path` NOT covered by `path` shifted by off (a crescent on the opposite side). */
function crescent(ctx, path, off, fillStyle, alpha = 1) {
  ctx.save();
  ctx.clip(path);
  const q = new Path2D();
  q.rect(-4000, -4000, 8000, 8000);
  q.addPath(path, new DOMMatrix().translate(off.x, off.y));
  ctx.globalAlpha *= alpha;
  ctx.fillStyle = fillStyle;
  ctx.fill(q, 'evenodd');
  ctx.restore();
}

/**
 * Paint one shape.
 * o = { fill, shade?, line, width, stroke?: Path2D (defaults to path), seed, pivot?: {x,y},
 *       noShade?, noRim?, noWeight?, lineColor?, hatchAlpha? }
 * env = { style, flags, scale (world units -> device px), boilTick }
 */
export function paint(ctx, path, o, env) {
  const S = env.style;
  const scale = env.scale || 1;
  const [lx, ly] = S.shade.light;
  const lineCol = S.line.colored ? o.lineColor || shadeHex(o.shade || o.fill, -0.55) : o.line;
  const lw = (o.width ?? 1.5) * 1.7 * S.line.scale;
  const stroke = o.stroke || path;
  const weight = env.flags.weight && !o.noWeight ? S.line.weight : 0;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  if (S.ink) {
    const m = toLocal(ctx, S.ink.misreg[0] * scale, S.ink.misreg[1] * scale);
    ctx.save();
    ctx.translate(m.x, m.y);
    ctx.fillStyle = o.fill;
    ctx.fill(path);
    ctx.restore();
    if (o.shade && !o.noShade) {
      const off = toLocal(ctx, lx * S.shade.band * scale, ly * S.shade.band * scale);
      crescent(ctx, path, off, hatchPattern(ctx, lineCol), o.hatchAlpha ?? 0.85);
    }
    const piv = o.pivot || { x: 0, y: 0 };
    const amp = S.ink.boil;
    for (let pass = 0; pass < S.ink.passes; pass++) {
      const r = (k) => hash((o.seed ?? 0) * 7 + pass * 131 + k, env.boilTick) - 0.5;
      ctx.save();
      ctx.translate(piv.x + r(1) * amp * 1.6, piv.y + r(2) * amp * 1.6);
      ctx.rotate(r(3) * amp * 0.05);
      ctx.translate(-piv.x, -piv.y);
      ctx.globalAlpha *= pass === 0 ? 1 : 0.55;
      ctx.strokeStyle = lineCol;
      ctx.lineWidth = lw * (pass === 0 ? 0.55 : 0.32);
      ctx.stroke(stroke);
      ctx.restore();
    }
    if (weight > 0) {
      const off = toLocal(ctx, -lx * weight * scale * 0.6, -ly * weight * scale * 0.6);
      ctx.save();
      ctx.translate(off.x, off.y);
      ctx.strokeStyle = lineCol;
      ctx.lineWidth = lw * 0.45;
      ctx.stroke(stroke);
      ctx.restore();
    }
    return;
  }

  if (weight > 0) {
    const off = toLocal(ctx, -lx * weight * scale, -ly * weight * scale);
    ctx.save();
    ctx.translate(off.x, off.y);
    ctx.strokeStyle = lineCol;
    ctx.lineWidth = lw * 0.75;
    ctx.stroke(stroke);
    ctx.restore();
  }
  ctx.strokeStyle = lineCol;
  ctx.lineWidth = lw;
  ctx.stroke(stroke);
  ctx.fillStyle = o.fill;
  ctx.fill(path);
  if (o.shade && !o.noShade && S.shade.band > 0) {
    const off = toLocal(ctx, lx * S.shade.band * scale, ly * S.shade.band * scale);
    crescent(ctx, path, off, o.shade, S.shade.hard ? 1 : 0.85);
  }
  if (S.rim && !o.noRim) {
    const off = toLocal(ctx, -lx * S.rim.width * scale, -ly * S.rim.width * scale);
    crescent(ctx, path, off, S.rim.color, S.rim.alpha);
  }
}

/** Thin interior line (creases, seams, zips). Boils in ink, tinted in cel. */
export function detailLine(ctx, path, color, width, env, seed = 0) {
  const S = env.style;
  ctx.save();
  ctx.lineCap = 'round';
  ctx.strokeStyle = color;
  ctx.lineWidth = width * Math.max(0.6, S.line.scale);
  if (S.ink) {
    const r = (k) => hash(seed * 13 + k, env.boilTick) - 0.5;
    ctx.translate(r(1) * S.ink.boil * 1.2, r(2) * S.ink.boil * 1.2);
  }
  ctx.stroke(path);
  ctx.restore();
}
